import {FERRY_STAGES,FLEET_BOATS,FLEET_ROUTES,ferryEligible,ferryFundingBlocker,ferryDeliveryBlocker,ferryPlan,ferryServiceBlocker} from './engine.js?v=0.20.1';
import {fleetHull} from './boat-art.js?v=0.20.1';

function ferryFundingView(cost,goal,view){return `<div class="cost">${view.costs(cost)}</div>${view.ingredients(cost,goal)}${view.goalTools(goal)}`;}
function ferryRemainingSupplies(supplies,batches){return Object.fromEntries(Object.entries(supplies).map(([key,count])=>[key,count*batches]));}
export function ferryEntryView(s){if(!ferryEligible(s))return '';return `<article class="build-card ferry-entry"><div class="panel-eyebrow">CHAPTER 05 · THE FERRY TERMINAL</div><h3>Give the harbour a new purpose.</h3><p>Build a passenger terminal in three stages. Furniture, cloth, food and construction supplies become a lasting connection to the coast.</p><button class="button secondary" data-action="go-ferry">${s.ferry.stage===3?'Manage passenger services':ferryEligible(s)?'Plan the ferry terminal':'Preview the ferry terminal'} →</button></article>`;}

function ferryStagesView(s,view){const f=s.ferry;return `<div class="ferry-stages">${FERRY_STAGES.map((stage,index)=>{
 const complete=index<f.stage,current=index===f.stage,funded=current&&f.funded,delivery=current?f.delivered:0,remaining=3-delivery;
 return `<article class="ferry-stage ${complete?'complete':current?'current':'future'}"><div class="panel-eyebrow">STAGE ${index+1} OF 3 ${complete?'· COMPLETE':funded?'· SUPPLY DELIVERIES':''}</div><h3>${stage.name}</h3><p>${stage.description}</p>${complete?'<span class="success-tag">Built · all three batches delivered</span>':!current?`<p class="hint">Funding: ${view.costs(stage.cost)}</p><p class="hint">Three supply batches: ${view.costs(ferryRemainingSupplies(stage.supplies,3))}</p><p class="hint">Complete the previous stage first.</p>`:!funded?`<div class="ferry-funding"><h4>1. Fund the work</h4>${ferryFundingView(stage.cost,'ferryfund:'+index,view)}<button class="button" data-action="ferry-fund" data-stage="${index}" ${ferryFundingBlocker(s)?'disabled':''}>Fund ${stage.name.toLowerCase()}</button>${ferryFundingBlocker(s)?`<p class="hint">${ferryFundingBlocker(s)}</p>`:''}</div><div class="ferry-supplies-preview"><h4>2. Prepare three supply batches</h4><p class="hint">Each batch needs ${view.costs(stage.supplies)}.</p><p class="hint">Total for this stage: ${view.costs(ferryRemainingSupplies(stage.supplies,3))}.</p><p class="hint">Funding pays for the work only. Deliver supplies separately when you are ready.</p></div>`:`<div class="ferry-delivery-progress"><strong>${delivery} / 3 batches delivered</strong><div class="ferry-batch-track" aria-label="${delivery} of 3 supply batches delivered">${[0,1,2].map(i=>`<span class="${i<delivery?'done':''}">${i<delivery?'✓':i+1}</span>`).join('')}</div></div><div class="ferry-funding"><h4>Next delivery · batch ${delivery+1}</h4>${ferryFundingView(stage.supplies,'ferry:'+index+':'+delivery,view)}<button class="button" data-action="ferry-deliver" data-stage="${index}" data-delivered="${delivery}" ${ferryDeliveryBlocker(s)?'disabled':''}>Deliver one supply batch</button>${ferryDeliveryBlocker(s)?`<p class="hint">${ferryDeliveryBlocker(s)}</p>`:''}<p class="hint">${remaining} ${remaining===1?'batch remains':'batches remain'}: ${view.costs(ferryRemainingSupplies(stage.supplies,remaining))} in total. Each delivery spends its goods once. The third delivery completes this stage immediately.</p></div>`}</article>`;
 }).join('')}</div>`;}
function ferryServicesView(s,view){return `<div class="ferry-service-heading"><div class="panel-eyebrow">PASSENGER SERVICES</div><h2>Choose what your fleet works on.</h2><p class="description">A passenger service uses the same boat as a cargo voyage. Load provisions, choose a destination and collect the fare when it returns. Passenger trips count as services, not trading visits.</p><div class="ferry-run-count"><strong>${s.ferry.runs}</strong><span>passenger services completed</span></div></div>${s.fleet.boats.map((boat,slot)=>{
 if(!boat)return `<article class="ferry-boat"><h3>Berth ${slot+1}</h3><p class="hint">Buy a boat in Fleet before assigning a passenger service.</p><button class="button secondary" data-action="fleet-boat" data-slot="${slot}">Choose a boat →</button></article>`;
 const t=boat.trip;
 let html=`<article class="ferry-boat"><div class="boat-summary">${fleetHull(boat.type)}<div><h3>${FLEET_BOATS[boat.type].name}</h3><p>Berth ${slot+1} · ${t?'At sea':'Available'}</p></div></div>`;
 if(t){html+=`<div class="ferry-current-trip"><div class="panel-eyebrow">${t.ferry?'PASSENGER SERVICE':t.stops?'CARGO CIRCUIT':'CARGO VOYAGE'}</div><h4>${t.stops?'Two-stop coastal circuit':FLEET_ROUTES[t.route].name}</h4><div class="progress"><i data-voyage-bar="${slot}"></i></div><p data-voyage-time="${slot}"></p><p class="hint">Loaded: ${view.costs(t.cargo)}.</p><div class="reward"><span>On return</span><strong>${view.costs(t.reward)}</strong></div><button class="button secondary" data-action="fleet-recall" data-slot="${slot}">Recall & return supplies</button><p class="hint">Recall refunds the loaded supplies, earns no fare, cargo reward or visit and stops repeat cargo trips.</p></div>`;}
 else html+=`<div class="ferry-destinations">${Object.keys(FLEET_ROUTES).map(route=>{const plan=ferryPlan(s,slot,route),reason=ferryServiceBlocker(s,slot,route);return `<section class="ferry-route"><h4>${FLEET_ROUTES[route].name}</h4>${plan?`<p class="hint">${plan.duration} simulation seconds · ${s.speed===0?'town paused':s.speed===3?'3× speed selected':'1× speed selected'}</p>${view.ingredients(plan.cost,plan.goal)}${view.goalTools(plan.goal)}<div class="reward"><span>Fare on return</span><strong>${view.costs(plan.reward)}</strong></div>`:''}<button class="button" data-action="ferry-depart" data-slot="${slot}" data-key="${route}" ${reason?'disabled':''}>Load & run service</button>${reason?`<p class="hint">${reason}</p>`:''}</section>`;}).join('')}</div><p class="hint">Starting a service stops this boat’s automatic cargo repeats. Services are dispatched manually; closing the game pauses progress.</p>`;
 return html+'</article>';
 }).join('')}`;}
export function ferryPanelView(s,view){const eligible=ferryEligible(s),f=s.ferry;return `<div class="panel-eyebrow">CHAPTER 05 · THE FERRY TERMINAL</div><div class="ferry-preview stage-${f.stage}" aria-hidden="true"></div><h2>${f.stage===3?'The harbour is open to passengers.':'Build the next connection.'}</h2><p class="description">Three permanent improvements connect your workshops to the waterfront. Fund each stage, then deliver three batches of supplies. Completed work stays built.</p><button class="text-button" data-action="district" data-key="coast">View the terminal on the coast →</button>${!eligible?'<div class="ferry-locked"><h3>Prepare the town first</h3><p>Open the new neighbourhood and finish the lighthouse to begin terminal construction.</p><button class="button secondary" data-action="go-neighbourhood">Plan the neighbourhood →</button><button class="text-button" data-action="fleet-view" data-key="lighthouse">View lighthouse restoration →</button></div>':''}${ferryStagesView(s,view)}${f.stage===3?ferryServicesView(s,view):'<p class="hint">Completing all three stages unlocks passenger services for your existing boats. Until then, cargo voyages and local production continue as usual.</p>'}`;}
